<?php
defined( 'ABSPATH' ) || exit;

/**
 * Customer reservation emails are generated by the plugin, outside the
 * theme's interface translation filter. Keep their small, fixed vocabulary
 * here so every supported enquiry language receives a complete message even
 * when no plugin MO file has been installed in the local WordPress clone.
 */
final class Rentacar_Core_Reservation_Translations {
    public static function get( $language, $key ) {
        $language = in_array( $language, array( 'it', 'ro', 'ru' ), true ) ? $language : 'en';
        $strings = self::strings();

        return $strings[ $language ][ $key ] ?? $strings['en'][ $key ] ?? $key;
    }

    public static function label( $language, $label ) {
        $labels = array(
            'it' => array( 'Child seat' => 'Seggiolino per bambini', 'Additional driver' => 'Guidatore aggiuntivo', 'Authorization for abroad' => 'Autorizzazione per l’estero', 'None' => 'Nessuno', 'Phone' => 'Telefono' ),
            'ro' => array( 'Child seat' => 'Scaun pentru copii', 'Additional driver' => 'Șofer suplimentar', 'Authorization for abroad' => 'Autorizație pentru călătorii în străinătate', 'None' => 'Niciunul', 'Phone' => 'Telefon' ),
            'ru' => array( 'Child seat' => 'Детское кресло', 'Additional driver' => 'Дополнительный водитель', 'Authorization for abroad' => 'Разрешение на выезд за границу', 'None' => 'Нет', 'Phone' => 'Телефон' ),
        );

        return isset( $labels[ $language ][ $label ] ) ? $labels[ $language ][ $label ] : $label;
    }

    public static function filter_gettext( $translated, $text, $domain ) {
        if ( 'rentacar-core' !== $domain ) {
            return $translated;
        }

        $language = Rentacar_Core_Language_Resolver_Factory::create()->current_language();
        $strings = array_replace_recursive( self::public_strings(), self::phone_public_strings() );

        return $strings[ $language ][ $text ] ?? $translated;
    }

